after.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & node .\scripts\verify-module-boundaries.mjs
  if ($LASTEXITCODE -ne 0) { throw "module boundary verification failed: $LASTEXITCODE" }
  & node .\scripts\verify-naming.mjs
  if ($LASTEXITCODE -ne 0) { throw "naming verification failed: $LASTEXITCODE" }
  & node .\scripts\verify-api-baseline.mjs
  if ($LASTEXITCODE -ne 0) { throw "API baseline verification failed: $LASTEXITCODE" }
  & .\gradlew.bat :ji-security-api:test :ji-credential-sqlite:test :ji-oauth-core:test :ji-error-catalog:test --offline --rerun-tasks
  if ($LASTEXITCODE -ne 0) { throw "credential/OAuth tests failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
